import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.EUByU7Iq.js";const p=JSON.parse('{"title":"第三章 物权的保护","description":"","frontmatter":{"title":"第三章 物权的保护","date":"2021-02-16T00:00:00.000Z","categories":["法律","民法典"],"tags":["法律","民法典"]},"headers":[],"relativePath":"blogs/CC/diyifenbian：tongze（disanzhang：wuquandebaohu）.md","filePath":"blogs/CC/第一分编：通则（第三章：物权的保护）.md"}'),i={name:"blogs/CC/diyifenbian：tongze（disanzhang：wuquandebaohu）.md"};function n(h,a,l,d,_,s){return t(),r("div",null,[...a[0]||(a[0]=[o('<h3 id="第二百三十三条" tabindex="-1">第二百三十三条 <a class="header-anchor" href="#第二百三十三条" aria-label="Permalink to &quot;第二百三十三条&quot;">​</a></h3><p>物权受到侵害的，权利人可以通过和解、调解、仲裁、诉讼等途径解决。</p><h3 id="第二百三十四条" tabindex="-1">第二百三十四条 <a class="header-anchor" href="#第二百三十四条" aria-label="Permalink to &quot;第二百三十四条&quot;">​</a></h3><p>因物权的归属、内容发生争议的，利害关系人可以请求确认权利。</p><h3 id="第二百三十五条" tabindex="-1">第二百三十五条 <a class="header-anchor" href="#第二百三十五条" aria-label="Permalink to &quot;第二百三十五条&quot;">​</a></h3><p>无权占有不动产或者动产的，权利人可以请求返还原物。</p><h3 id="第二百三十六条" tabindex="-1">第二百三十六条 <a class="header-anchor" href="#第二百三十六条" aria-label="Permalink to &quot;第二百三十六条&quot;">​</a></h3><p>妨害物权或者可能妨害物权的，权利人可以请求排除妨害或者消除危险。</p><h3 id="第二百三十七条" tabindex="-1">第二百三十七条 <a class="header-anchor" href="#第二百三十七条" aria-label="Permalink to &quot;第二百三十七条&quot;">​</a></h3><p>造成不动产或者动产毁损的，权利人可以依法请求修理、重作、更换或者恢复原状。</p><h3 id="第二百三十八条" tabindex="-1">第二百三十八条 <a class="header-anchor" href="#第二百三十八条" aria-label="Permalink to &quot;第二百三十八条&quot;">​</a></h3><p>侵害物权，造成权利人损害的，权利人可以依法请求损害赔偿，也可以依法请求承担其他民事责任。</p><h3 id="第二百三十九条" tabindex="-1">第二百三十九条 <a class="header-anchor" href="#第二百三十九条" aria-label="Permalink to &quot;第二百三十九条&quot;">​</a></h3><p>本章规定的物权保护方式，可以单独适用，也可以根据权利被侵害的情形合并适用。</p>',14)])])}const u=e(i,[["render",n]]);export{p as __pageData,u as default};
